from sortedcontainers import SortedList
class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        cb = [0] * (n + 2); sb = [0] * (n + 2)
        def upd(b, i, v):
            while i <= n: b[i] += v; i += i & (-i)
        def qry(b, i):
            s = 0
            while i > 0: s += b[i]; i -= i & (-i)
            return s
        def mAdd(t):
            if t > 0: upd(cb, t, 1); upd(sb, t, t)
        def mDel(t):
            if t > 0: upd(cb, t, -1); upd(sb, t, -t)
        F = SortedList()
        def pred(e):
            i = F.bisect_left(e)
            return F[i - 1] if i > 0 else F[-1]
        def succ(e):
            i = F.bisect_right(e)
            return F[i] if i < len(F) else F[0]
        def toggle(e, toBad):
            if toBad:
                if not F:
                    mDel(n); F.add(e); mAdd(n - 1)
                elif len(F) == 1:
                    f = F[0]; mDel(n - 1); F.add(e)
                    mAdd((e - f - 1) % n); mAdd((f - e - 1) % n)
                else:
                    l, r = pred(e), succ(e)
                    mDel((r - l - 1) % n); F.add(e)
                    mAdd((e - l - 1) % n); mAdd((r - e - 1) % n)
            else:
                if len(F) == 1:
                    mDel(n - 1); F.clear(); mAdd(n)
                elif len(F) == 2:
                    o = F[0] if F[1] == e else F[1]
                    mDel((e - o - 1) % n); mDel((o - e - 1) % n)
                    F.remove(e); mAdd(n - 1)
                else:
                    l, r = pred(e), succ(e)
                    mDel((e - l - 1) % n); mDel((r - e - 1) % n)
                    F.remove(e); mAdd((r - l - 1) % n)
        for i in range(n):
            if colors[i] == colors[(i + 1) % n]: F.add(i)
        if not F: mAdd(n)
        elif len(F) == 1: mAdd(n - 1)
        else:
            for a, b in zip(F, list(F[1:]) + [F[0]]): mAdd((b - a - 1) % n)
        ans = []
        for q in queries:
            if q[0] == 1:
                s = q[1]
                if not F: ans.append(n)
                else:
                    lo = s - 1
                    c = qry(cb, n) - qry(cb, lo - 1)
                    sm = qry(sb, n) - qry(sb, lo - 1)
                    ans.append(sm - (s - 2) * c)
            else:
                _, idx, col = q
                colors[idx] = col
                for e in (idx, (idx - 1) % n):
                    good = colors[e] != colors[(e + 1) % n]
                    if good == (e in F): continue
                    toggle(e, not good)
        return ans

