class Solution {
    int n;
    vector<long long> cb, sb;
    set<int> F;
    void upd(vector<long long>& b, int i, long long v) {
        for (; i <= n; i += i & (-i)) b[i] += v;
    }
    long long qry(vector<long long>& b, int i) {
        long long s = 0;
        for (; i > 0; i -= i & (-i)) s += b[i];
        return s;
    }
    void mAdd(int t) { if (t > 0) { upd(cb, t, 1); upd(sb, t, t); } }
    void mDel(int t) { if (t > 0) { upd(cb, t, -1); upd(sb, t, -t); } }
    int pred(int e) { auto it = F.lower_bound(e); return it == F.begin() ? *F.rbegin() : *prev(it); }
    int succ(int e) { auto it = F.upper_bound(e); return it == F.end() ? *F.begin() : *it; }
    void toggle(int e, bool toBad) {
        if (toBad) {
            if (F.empty()) { mDel(n); F.insert(e); mAdd(n - 1); }
            else if (F.size() == 1) {
                int f = *F.begin(); mDel(n - 1); F.insert(e);
                mAdd(((e - f - 1) % n + n) % n); mAdd(((f - e - 1) % n + n) % n);
            } else {
                int l = pred(e), r = succ(e);
                mDel(((r - l - 1) % n + n) % n); F.insert(e);
                mAdd(((e - l - 1) % n + n) % n); mAdd(((r - e - 1) % n + n) % n);
            }
        } else {
            if (F.size() == 1) { mDel(n - 1); F.erase(e); mAdd(n); }
            else if (F.size() == 2) {
                int o = (*F.begin() == e) ? *F.rbegin() : *F.begin();
                mDel(((e - o - 1) % n + n) % n); mDel(((o - e - 1) % n + n) % n);
                F.erase(e); mAdd(n - 1);
            } else {
                int l = pred(e), r = succ(e);
                mDel(((e - l - 1) % n + n) % n); mDel(((r - e - 1) % n + n) % n);
                F.erase(e); mAdd(((r - l - 1) % n + n) % n);
            }
        }
    }
public:
    vector<int> numberOfAlternatingGroups(vector<int>& colors, vector<vector<int>>& queries) {
        n = colors.size();
        cb.assign(n + 2, 0); sb.assign(n + 2, 0);
        for (int i = 0; i < n; i++)
            if (colors[i] == colors[(i + 1) % n]) F.insert(i);
        if (F.empty()) mAdd(n);
        else if (F.size() == 1) mAdd(n - 1);
        else {
            vector<int> v(F.begin(), F.end());
            for (size_t i = 0; i < v.size(); i++)
                mAdd(((v[(i + 1) % v.size()] - v[i] - 1) % n + n) % n);
        }
        vector<int> ans;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int s = q[1];
                if (F.empty()) ans.push_back(n);
                else {
                    int lo = s - 1;
                    long long c = qry(cb, n) - qry(cb, lo - 1);
                    long long sm = qry(sb, n) - qry(sb, lo - 1);
                    ans.push_back((int)(sm - (long long)(s - 2) * c));
                }
            } else {
                int idx = q[1], col = q[2];
                colors[idx] = col;
                int es[2] = {idx, (idx - 1 + n) % n};
                for (int e : es) {
                    bool good = colors[e] != colors[(e + 1) % n];
                    if (good == (F.count(e) > 0)) continue;
                    toggle(e, !good);
                }
            }
        }
        return ans;
    }
};

