class Solution {
    private int n;
    private long[] cb, sb;
    private TreeSet<Integer> F = new TreeSet<>();
    private void upd(long[] b, int i, long v) { for (; i <= n; i += i & (-i)) b[i] += v; }
    private long qry(long[] b, int i) { long s = 0; for (; i > 0; i -= i & (-i)) s += b[i]; return s; }
    private void mAdd(int t) { if (t > 0) { upd(cb, t, 1); upd(sb, t, t); } }
    private void mDel(int t) { if (t > 0) { upd(cb, t, -1); upd(sb, t, -t); } }
    private int pred(int e) { return F.floor(e - 1) != null ? F.floor(e - 1) : F.last(); }
    private int succ(int e) { return F.ceiling(e + 1) != null ? F.ceiling(e + 1) : F.first(); }
    private int cyc(int x) { return ((x % n) + n) % n; }
    private void toggle(int e, boolean toBad) {
        if (toBad) {
            if (F.isEmpty()) { mDel(n); F.add(e); mAdd(n - 1); }
            else if (F.size() == 1) {
                int f = F.first(); mDel(n - 1); F.add(e);
                mAdd(cyc(e - f - 1)); mAdd(cyc(f - e - 1));
            } else {
                int l = pred(e), r = succ(e);
                mDel(cyc(r - l - 1)); F.add(e);
                mAdd(cyc(e - l - 1)); mAdd(cyc(r - e - 1));
            }
        } else {
            if (F.size() == 1) { mDel(n - 1); F.remove(e); mAdd(n); }
            else if (F.size() == 2) {
                int o = F.first().equals(e) ? F.last() : F.first();
                mDel(cyc(e - o - 1)); mDel(cyc(o - e - 1));
                F.remove(e); mAdd(n - 1);
            } else {
                int l = pred(e), r = succ(e);
                mDel(cyc(e - l - 1)); mDel(cyc(r - e - 1));
                F.remove(e); mAdd(cyc(r - l - 1));
            }
        }
    }
    public int[] numberOfAlternatingGroups(int[] colors, int[][] queries) {
        n = colors.length;
        cb = new long[n + 2]; sb = new long[n + 2];
        for (int i = 0; i < n; i++)
            if (colors[i] == colors[(i + 1) % n]) F.add(i);
        if (F.isEmpty()) mAdd(n);
        else if (F.size() == 1) mAdd(n - 1);
        else {
            List<Integer> v = new ArrayList<>(F);
            for (int i = 0; i < v.size(); i++) mAdd(cyc(v.get((i + 1) % v.size()) - v.get(i) - 1));
        }
        List<Integer> res = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int s = q[1];
                if (F.isEmpty()) res.add(n);
                else {
                    int lo = s - 1;
                    long c = qry(cb, n) - qry(cb, lo - 1);
                    long sm = qry(sb, n) - qry(sb, lo - 1);
                    res.add((int) (sm - (long) (s - 2) * c));
                }
            } else {
                int idx = q[1], col = q[2];
                colors[idx] = col;
                int[] es = {idx, (idx - 1 + n) % n};
                for (int e : es) {
                    boolean good = colors[e] != colors[(e + 1) % n];
                    if (good == F.contains(e)) continue;
                    toggle(e, !good);
                }
            }
        }
        return res.stream().mapToInt(Integer::intValue).toArray();
    }
}

