var numberOfAlternatingGroups = function(colors, queries) {
    const n = colors.length;
    const cb = new Array(n + 2).fill(0), sb = new Array(n + 2).fill(0);
    const fw = new Array(n + 1).fill(0);
    let total = 0;
    const fupd = (i, v) => { for (i++; i <= n; i += i & -i) fw[i] += v; };
    const fq = (i) => { let s = 0; for (i++; i > 0; i -= i & -i) s += fw[i]; return s; };
    const kth = (k) => {
        let pos = 0, rem = k;
        for (let pw = 1 << Math.floor(Math.log2(Math.max(n,1))); pw > 0; pw >>= 1)
            if (pos + pw <= n && fw[pos + pw] < rem) { pos += pw; rem -= fw[pos]; }
        return pos;
    };
    const pred = (e) => { const c = fq(e - 1); return c > 0 ? kth(c) : kth(total); };
    const succ = (e) => { const c = fq(e); return c < total ? kth(c + 1) : kth(1); };
    const has = (e) => fq(e) - fq(e - 1) > 0;
    const upd = (b, i, v) => { for (; i <= n; i += i & -i) b[i] += v; };
    const qry = (b, i) => { let s = 0; for (; i > 0; i -= i & -i) s += b[i]; return s; };
    const mAdd = (t) => { if (t > 0) { upd(cb, t, 1); upd(sb, t, t); } };
    const mDel = (t) => { if (t > 0) { upd(cb, t, -1); upd(sb, t, -t); } };
    const cyc = (x) => ((x % n) + n) % n;
    const toggle = (e, toBad) => {
        if (toBad) {
            if (total === 0) { mDel(n); fupd(e, 1); total++; mAdd(n - 1); }
            else if (total === 1) {
                const f = kth(1); mDel(n - 1); fupd(e, 1); total++;
                mAdd(cyc(e - f - 1)); mAdd(cyc(f - e - 1));
            } else {
                const l = pred(e), r = succ(e);
                mDel(cyc(r - l - 1)); fupd(e, 1); total++;
                mAdd(cyc(e - l - 1)); mAdd(cyc(r - e - 1));
            }
        } else {
            if (total === 1) { mDel(n - 1); fupd(e, -1); total--; mAdd(n); }
            else if (total === 2) {
                const o = kth(1) === e ? kth(2) : kth(1);
                mDel(cyc(e - o - 1)); mDel(cyc(o - e - 1));
                fupd(e, -1); total--; mAdd(n - 1);
            } else {
                const l = pred(e), r = succ(e);
                mDel(cyc(e - l - 1)); mDel(cyc(r - e - 1));
                fupd(e, -1); total--; mAdd(cyc(r - l - 1));
            }
        }
    };
    for (let i = 0; i < n; i++)
        if (colors[i] === colors[(i + 1) % n]) { fupd(i, 1); total++; }
    if (total === 0) mAdd(n);
    else if (total === 1) mAdd(n - 1);
    else {
        const v = []; for (let e = 0; e < n; e++) if (has(e)) v.push(e);
        for (let i = 0; i < v.length; i++) mAdd(cyc(v[(i + 1) % v.length] - v[i] - 1));
    }
    const ans = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const s = q[1];
            if (total === 0) ans.push(n);
            else {
                const lo = s - 1;
                const c = qry(cb, n) - qry(cb, lo - 1);
                const sm = qry(sb, n) - qry(sb, lo - 1);
                ans.push(sm - (s - 2) * c);
            }
        } else {
            const [, idx, col] = q;
            colors[idx] = col;
            for (const e of [idx, (idx - 1 + n) % n]) {
                const good = colors[e] !== colors[(e + 1) % n];
                if (good === has(e)) continue;
                toggle(e, !good);
            }
        }
    }
    return ans;
};
